import{_ as r,o,c as l,ah as e}from"./chunks/framework.DjU4PSOm.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[{"level":2,"title":"1. 기본 배경","slug":"_1-기본-배경","link":"#_1-기본-배경","children":[]},{"level":2,"title":"2. 감각과 지각","slug":"_2-감각과-지각","link":"#_2-감각과-지각","children":[]},{"level":2,"title":"3. 자기-몸 (corps propre)","slug":"_3-자기-몸-corps-propre","link":"#_3-자기-몸-corps-propre","children":[{"level":3,"title":"환상지 & 질병실인증","slug":"환상지-질병실인증","link":"#환상지-질병실인증","children":[]}]},{"level":2,"title":"4. 자기-몸의 공간과 운동","slug":"_4-자기-몸의-공간과-운동","link":"#_4-자기-몸의-공간과-운동","children":[]},{"level":2,"title":"5. 자기-몸의 성과 언어","slug":"_5-자기-몸의-성과-언어","link":"#_5-자기-몸의-성과-언어","children":[]},{"level":2,"title":"6. 물질과 정신의 통일성","slug":"_6-물질과-정신의-통일성","link":"#_6-물질과-정신의-통일성","children":[]},{"level":2,"title":"7. 시험 대비 핵심 개념 체크리스트","slug":"_7-시험-대비-핵심-개념-체크리스트","link":"#_7-시험-대비-핵심-개념-체크리스트","children":[]}],"relativePath":"philosophy/Phenomenology/06. 메를로퐁티.md","filePath":"philosophy/Phenomenology/06. 메를로퐁티.md"}'),n={name:"philosophy/Phenomenology/06. 메를로퐁티.md"};function s(a,t,i,d,h,g){return o(),l("div",null,[...t[0]||(t[0]=[e('<h2 id="_1-기본-배경" tabindex="-1">1. 기본 배경 <a class="header-anchor" href="#_1-기본-배경" aria-label="Permalink to &quot;1. 기본 배경&quot;">​</a></h2><p><strong>『지각의 현상학』(1945)</strong>이 핵심 텍스트. 심리학 논의에 개입하면서 <strong>경험주의</strong>와 <strong>지성주의</strong> 둘 다 비판함.</p><ul><li>경험주의 = 마음을 생물학적·감각주의적으로 설명</li><li>지성주의 = 마음을 순수한 사고·인식으로 설명</li><li>메를로퐁티의 결론: <strong>삶에서 암묵적·실천적으로 경험되는 몸이 마음의 본질</strong></li></ul><h2 id="_2-감각과-지각" tabindex="-1">2. 감각과 지각 <a class="header-anchor" href="#_2-감각과-지각" aria-label="Permalink to &quot;2. 감각과 지각&quot;">​</a></h2><p>감각적 현상은 의식이 아니라 대상에 속함.</p><p><strong>핵심 주장: 지각적 전체론</strong> — 감각은 지각에 앞서지 않고, 지각으로부터 분리될 수 없음. 객관적 세계에 괄호치고 생활세계로 돌아가야 하지만, 메를로퐁티는 완전한 에포케는 불가능하다고 봄 — 애초에 지각이라는 게 몸과 함께 이뤄지는 것이라, 몸도 없어야 세계에 대한 완전한 괄호가 가능해지기 때문.</p><table tabindex="0"><thead><tr><th>비판 대상</th><th>주장</th><th>메를로퐁티의 반론</th></tr></thead><tbody><tr><td>경험주의</td><td>지각 = 감각들의 연합 (항상성 가설: 자극↔감각 1:1 대응)</td><td>감각적 현상은 대상이 삶에 대해 가지는 의미에서 분리 불가</td></tr><tr><td>지성주의</td><td>지각 = 감각에 대한 추론·해석</td><td>지각에 앞서 주어진 감각 자체가 없음</td></tr></tbody></table><p>감각적 현상은 몸에 대해 가지는 의미로부터 분리될 수 없음.</p><p><strong>뮐러-라이어 착시</strong> 예시: 두 직선이 삶에 대해 다른 의미를 가지기 때문에 감각적 현상 자체가 달라짐. 리버스의 연구처럼 생활 공간이 착시에 영향을 미침 → 지각은 몸과 삶의 맥락과 분리 불가.</p><p><strong>→ 따라서 철학의 첫 번째 과제</strong>: 객관적 세계(물리·생물학적 세계)에 괄호를 치고 <strong>체험된 세계(생활세계)</strong>로 돌아가는 것.</p><h2 id="_3-자기-몸-corps-propre" tabindex="-1">3. 자기-몸 (corps propre) <a class="header-anchor" href="#_3-자기-몸-corps-propre" aria-label="Permalink to &quot;3. 자기-몸 (corps propre)&quot;">​</a></h2><p>고유감각을 통해 경험되는 몸. 지각의 결정적 요소.</p><h3 id="환상지-질병실인증" tabindex="-1">환상지 &amp; 질병실인증 <a class="header-anchor" href="#환상지-질병실인증" aria-label="Permalink to &quot;환상지 &amp; 질병실인증&quot;">​</a></h3><table tabindex="0"><thead><tr><th>증상</th><th>정의</th><th>경험주의 설명 (비판됨)</th><th>지성주의 설명 (비판됨)</th><th>메를로퐁티의 설명</th></tr></thead><tbody><tr><td>환상지</td><td>절단된 팔다리를 여전히 느낌</td><td>비정상적 감각의 산물</td><td>몸에 대한 잘못된 인식</td><td>절단 전의 <strong>실천적 장</strong>을 간직하는 것</td></tr><tr><td>질병실인증</td><td>자신의 질병을 인식 못함</td><td>비정상적 감각의 산물</td><td>몸에 대한 잘못된 인식</td><td>자신의 장애를 <strong>암묵적으로</strong> 알면서 실천적 환경 속 자아가 부정하는 것</td></tr></tbody></table><p><strong>→ 핵심 개념: 세계에 있는 존재(être-au-monde)</strong> — 주체가 실천적 환경에서 경험하는 몸. 이러저러하게 움직일 수 있는 것으로서 암묵적으로 경험되는 몸.</p><h2 id="_4-자기-몸의-공간과-운동" tabindex="-1">4. 자기-몸의 공간과 운동 <a class="header-anchor" href="#_4-자기-몸의-공간과-운동" aria-label="Permalink to &quot;4. 자기-몸의 공간과 운동&quot;">​</a></h2><p><strong>신체 도식 (body schema)</strong>: 자신의 몸이 나타나는 모습. <strong>실천적 과제를 중심으로 구성됨.</strong> 몸의 공간성은 위치의 공간성이 아니라 <strong>상황의 공간성</strong>.</p><p><strong>슈나이더 사례 (정신맹 환자)</strong>: 눈을 감으면 <strong>추상적 운동</strong>(구체적 상황에 관련되지 않는 운동, 예: 명령에 따라 손가락 펴기)을 못함.</p><ul><li>경험주의 비판: 시각 장애로 설명 안 됨 → 시각이 변해도 촉각 능력도 함께 변함. 분리해서 인과 설명 불가.</li><li>지성주의 비판: 인식 능력 결함으로 설명 안 됨 → 환자는 개념적 분석·포섭은 잘 하지만, 직접적으로 이해되어야 할 단순한 유비를 이해 못함.</li></ul><p><strong>지향궁 (intentional arc)</strong>: 자극에서 반응까지 이르는 <strong>지향적 경로</strong> (cf. 반사궁은 신경 경로).</p><blockquote><p>촉발하는 대상에 대해 자신의 몸을 가능한 상황에 <strong>투사</strong>하면서 행동하는 능력</p></blockquote><p>슈나이더의 문제 = 지향궁이 &quot;느슨해진&quot; 것. 몸을 가능한 상황에 폭넓게 투사하지 못해서 추상적 운동, 유비, 사회, 이념, 도덕을 이해하는 데 모두 어려움을 겪음.</p><p><strong>→ 의식의 본래 형태는 &quot;나는 사유한다&quot;가 아니라 &quot;나는 할 수 있다&quot;</strong></p><h2 id="_5-자기-몸의-성과-언어" tabindex="-1">5. 자기-몸의 성과 언어 <a class="header-anchor" href="#_5-자기-몸의-성과-언어" aria-label="Permalink to &quot;5. 자기-몸의 성과 언어&quot;">​</a></h2><p>두 영역 모두 동일한 구조: <strong>경험주의도 지성주의도 아닌 몸의 차원에서 이해됨</strong>.</p><p><strong>성 (sexuality)</strong></p><ul><li>성적 행동 = 생물학적인 것도, 순수 지성적인 것도 아님</li><li>슈나이더의 성적 장애 = 지향궁의 결함으로 설명</li><li><strong>성적 행동은 그 자체로 실존적 태도임</strong> (단순한 표출·증상이 아님)</li><li>&quot;욕망은 몸에 몸을 연결함으로써 맹목적으로 이해한다&quot;</li></ul><p><strong>언어 (parole)</strong></p><ul><li>경험주의: 말 = 생물학적/연합적 산물 → 말 자체에는 의미 없음</li><li>지성주의: 말 = 내적 사고의 외적 기호 → 말 없이도 사고 성립, 말은 기여 없음</li><li>메를로퐁티: <strong>말은 사고를 전제하는 것이 아니라 사고를 실현하는 것</strong></li><li>&quot;몸은 가리키는 것이고, 말하는 것이다&quot;</li></ul><h2 id="_6-물질과-정신의-통일성" tabindex="-1">6. 물질과 정신의 통일성 <a class="header-anchor" href="#_6-물질과-정신의-통일성" aria-label="Permalink to &quot;6. 물질과 정신의 통일성&quot;">​</a></h2><p><strong>자기-몸의 애매성</strong>: 운동 ↔ 의식, 성적 행동 ↔ 실존적 태도, 말 ↔ 사고가 <strong>구별되지 않음</strong> → <strong>애매성의 철학</strong></p><table tabindex="0"><thead><tr><th></th><th>데카르트적 반성</th><th>자기-몸의 경험</th></tr></thead><tbody><tr><td>물질</td><td>기하학적 연장</td><td>살아있는 몸</td></tr><tr><td>정신</td><td>순수한 사고 (노에시스)</td><td>몸과 통일된 의식</td></tr><tr><td>관계</td><td>분리 (명석·판명)</td><td>통일 (애매·모호)</td></tr></tbody></table><p><strong>→ 자기-몸이 물질인 동시에 정신</strong></p><p><strong>살의 존재론</strong> (후기 작업, 『보이는 것과 보이지 않는 것』): 자기-몸을 이루는 요소인 &#39;살&#39;을 물질과 정신의 형이상학적 근원으로 파악하려는 시도.</p><h2 id="_7-시험-대비-핵심-개념-체크리스트" tabindex="-1">7. 시험 대비 핵심 개념 체크리스트 <a class="header-anchor" href="#_7-시험-대비-핵심-개념-체크리스트" aria-label="Permalink to &quot;7. 시험 대비 핵심 개념 체크리스트&quot;">​</a></h2><p>감각적 현상은 의식이 아니라 대상에 속함.</p><ul><li><strong>지각적 전체론</strong>: 감각 ≠ 지각의 전제, 지각으로부터 분리 불가</li><li><strong>자기-몸</strong>: 고유감각으로 경험되는 몸, 실천적 환경 속에서 경험됨</li><li><strong>세계에 있는 존재</strong>: 실천적 환경 속 주체</li><li><strong>신체 도식</strong>: 실천적 과제 중심으로 구성된 몸의 모습, 상황의 공간성</li><li><strong>지향궁</strong>: 가능한 상황에 몸을 투사하는 능력 (반사궁과 대조)</li><li><strong>애매성</strong>: 물질·정신, 몸·의식이 구별되지 않는 자기-몸의 특성</li><li><strong>&quot;나는 할 수 있다&quot;</strong>: 의식의 본래 형태는 사유가 아닌 운동성</li></ul>',37)])])}const u=r(n,[["render",s]]);export{_ as __pageData,u as default};
